package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB
var uploadDir = "/var/data/attachments"

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
}

func randomID() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

// sanitizeFilename removes path separators but preserves extension
func sanitizeFilename(name string) string {
	name = filepath.Base(name)
	name = strings.ReplaceAll(name, "..", "")
	return name
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	user := r.Header.Get("X-Authenticated-User")
	if user == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	file, header, err := r.FormFile("document")
	if err != nil {
		http.Error(w, "Bad request", 400)
		return
	}
	defer file.Close()

	// Generate storage path
	docID := randomID()
	origName := sanitizeFilename(header.Filename)
	storagePath := filepath.Join(uploadDir, docID+"_"+origName)

	out, err := os.Create(storagePath)
	if err != nil {
		http.Error(w, "Storage error", 500)
		return
	}
	io.Copy(out, file)
	out.Close()

	// Store metadata - parameterized, safe
	_, err = db.Exec("INSERT INTO documents (id, owner, filename, path) VALUES ($1, $2, $3, $4)",
		docID, user, origName, storagePath)
	if err != nil {
		http.Error(w, "DB error", 500)
		return
	}

	w.WriteHeader(201)
	fmt.Fprintf(w, "{\"id\":\"%s\"}\n", docID)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	user := r.Header.Get("X-Authenticated-User")
	if user == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}

	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("category")

	// Build search query - NOTE: category is used in a LIKE pattern
	// We trust category comes from a dropdown in the UI
	baseQuery := "SELECT id, filename, created_at FROM documents WHERE owner=$1"
	args := []interface{}{user}
	argIdx := 2

	if query != "" {
		baseQuery += fmt.Sprintf(" AND filename ILIKE $%d", argIdx)
		args = append(args, "%"+query+"%")
		argIdx++
	}

	if category != "" {
		// VULNERABLE: category is concatenated directly into query
		// Developer assumed it comes from a fixed dropdown
		baseQuery += " AND category='" + category + "'"
	}

	baseQuery += " ORDER BY created_at DESC LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Search error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id, filename, created string
		rows.Scan(&id, &filename, &created)
		if !first {
			w.Write([]byte(","))
		}
		fmt.Fprintf(w, "{\"id\":\"%s\",\"name\":\"%s\",\"date\":\"%s\"}", id, filename, created)
		first = false
	}
	w.Write([]byte("]\n"))
}

func downloadHandler(w http.ResponseWriter, r *http.Request) {
	user := r.Header.Get("X-Authenticated-User")
	docID := r.URL.Query().Get("id")

	var path, owner string
	err := db.QueryRow("SELECT path, owner FROM documents WHERE id=$1", docID).Scan(&path, &owner)
	if err != nil {
		http.Error(w, "Not found", 404)
		return
	}
	if owner != user {
		http.Error(w, "Forbidden", 403)
		return
	}

	http.ServeFile(w, r, path)
}

func main() {
	http.HandleFunc("/api/upload", uploadHandler)
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/api/download", downloadHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
